// ThemeSwitch.js
// Site-wide light/dark switch, after @kaolti's dot-matrix toggle: a recessed
// track, a glass squircle knob on a spring, and an 11×11 dot icon whose
// pixels scatter and re-form between a moon (dark) and a sun (light).
// Night: smoky glass with violet light underneath. Day: milk glass with a
// warm amber rim.

import React, { useState } from "react";
import "./ThemeSwitch.css";

const N = 11;
const bitsFrom = (test) => {
  const on = new Set();
  for (let y = 0; y < N; y++)
    for (let x = 0; x < N; x++) if (test(x, y)) on.add(y * N + x);
  return on;
};

// Hand-drawn so it reads as a crescent at 11×11 (a computed one looked like a hook).
const fromRows = (rows) => {
  const on = new Set();
  rows.forEach((r, y) =>
    [...r].forEach((c, x) => c === "#" && on.add(y * N + x))
  );
  return on;
};
const MOON = fromRows([
  "....###....",
  "..####..#..",
  ".####..###.",
  ".###....#..",
  "###........",
  "###........",
  "###........",
  ".###.......",
  ".####......",
  "..####.....",
  "....###....",
]);

const SUN = (() => {
  const s = bitsFrom((x, y) => Math.hypot(x - 5, y - 5) <= 2.2);
  [
    [5, 0],
    [5, 1],
    [5, 9],
    [5, 10],
    [0, 5],
    [1, 5],
    [9, 5],
    [10, 5],
    [1, 1],
    [2, 2],
    [8, 8],
    [9, 9],
    [1, 9],
    [2, 8],
    [8, 2],
    [9, 1],
  ].forEach(([x, y]) => s.add(y * N + x));
  return s;
})();

// Stable per-dot stagger so the morph scatters rather than wipes.
const DELAYS = Array.from({ length: N * N }, (_, i) => {
  let h = 2166136261;
  const str = `t${i}`;
  for (let k = 0; k < str.length; k++)
    h = Math.imul(h ^ str.charCodeAt(k), 16777619);
  return (((h >>> 0) % 1000) / 1000) * 240;
});

export default function ThemeSwitch({ isDark, onToggle }) {
  const bits = isDark ? MOON : SUN;
  // The slide animation should play on a click, not on every page load.
  const [touched, setTouched] = useState(false);
  return (
    <button
      type="button"
      className={`dm-switch ${isDark ? "is-dark" : "is-light"} ${
        touched ? "dm-touched" : ""
      }`}
      role="switch"
      aria-checked={isDark}
      aria-label={
        isDark
          ? "Dark mode on. Switch to light mode"
          : "Light mode on. Switch to dark mode"
      }
      title={isDark ? "Switch to light mode" : "Switch to dark mode"}
      onClick={() => {
        setTouched(true);
        onToggle();
      }}
    >
      <span className="dm-pool" aria-hidden="true" />
      <span className="dm-knob">
        <span className="dm-dots" aria-hidden="true">
          {Array.from({ length: N * N }, (_, i) => (
            <i
              key={i}
              className={bits.has(i) ? "on" : ""}
              style={{ transitionDelay: `${DELAYS[i]}ms` }}
            />
          ))}
        </span>
      </span>
    </button>
  );
}
