// The route hop — the light leaping from the key you were on to the key you
// asked for — deliberately lives outside React.
//
// Two measured facts about this app forced that:
//
//   1. Every page renders its own <Header> (src/pages/*), so a route change
//      tears the whole bar down and builds a new one. An animation owned by the
//      header is therefore destroyed mid-flight by the very navigation it is
//      animating.
//   2. That commit blocks the main thread — ~30ms for Blogs, ~300ms for Home,
//      and over a second for the heaviest pages. Anything that starts when the
//      new header mounts starts inside a window where nothing is being painted.
//      (Measured: animationstart and animationend for the whole hop arriving in
//      the same millisecond, 1163ms after the click.)
//
// So the flight is a plain DOM node on document.body, built the instant a nav
// link is clicked — before React commits anything — and animated only on
// transform and opacity, which the compositor keeps running while the main
// thread is busy rebuilding the page. It outlives the header that launched it.
//
// The header still owns what happens *to the keys* (the impact, the dip, the
// ignition): those belong to whichever header is on screen when the ball
// arrives, and it reads them off the flight record with takeFlight().

const LAYER_CLASS = "nav-hop-layer";

// Ghost copies of the ball, each one launched slightly later along the same
// path, which is what draws the trail. Enough of them, close enough together,
// that it reads as a streak rather than as a row of beads.
const GHOSTS = 5;
const GHOST_GAP_MS = 16;

// Travel time grows with distance, so a hop to the far end of the row does not
// look teleported — but it never drags either.
export const hopDuration = (dist) => Math.round(Math.min(720, 290 + dist * 0.46));

// The flight the next <Header> to mount should finish: where the ball is
// landing, when it gets there, and which keys it skims on the way.
let flight = null;

const centre = (rect) => ({
  x: rect.left + rect.width / 2,
  y: rect.top + rect.height / 2,
});

const accentOf = (el, fallback) =>
  getComputedStyle(el).getPropertyValue("--accent").trim() || fallback;

const setVars = (el, vars) => {
  Object.keys(vars).forEach((k) => el.style.setProperty(k, vars[k]));
};

/**
 * Launch a hop. Returns the flight record, or null if there is nothing to
 * animate between.
 *
 * @param fromEl  the key being left
 * @param toEl    the key being arrived at
 * @param toIdx   that key's index in NAV_ITEMS
 * @param keys    all nav link elements, for the keys skimmed en route
 */
export function startNavHop({ fromEl, toEl, toIdx, keys }) {
  if (!fromEl || !toEl || typeof document === "undefined") return null;

  const fromRect = fromEl.getBoundingClientRect();
  const toRect = toEl.getBoundingClientRect();
  const from = centre(fromRect);
  const to = centre(toRect);
  const dist = Math.hypot(to.x - from.x, to.y - from.y);
  if (dist < 1) return null;

  const dur = hopDuration(dist);

  // The bar sits against the top of the window, so the arc has only the strip
  // above the caps to play in — roughly 17px on this header. Distance still
  // scales the height, but the apex is clamped to stay on screen: measured
  // without this, a cross-row hop peaked at y = -1 and left the viewport.
  const ceiling = Math.max(12, Math.min(from.y, to.y) - 7);
  const arc = Math.min(
    ceiling,
    toRect.height / 2 + Math.min(22, Math.max(9, dist * 0.06))
  );

  const accent = accentOf(toEl, "#7cd1f7");
  const accentFrom = accentOf(fromEl, accent);

  // Keys under the flight path dip as the ball goes over them. Offsets are
  // from the start of the flight.
  const wake = {};
  const span = to.x - from.x || 1;
  (keys || []).forEach((el, i) => {
    if (!el || el === fromEl || el === toEl) return;
    const t = (centre(el.getBoundingClientRect()).x - from.x) / span;
    if (t > 0.05 && t < 0.95) wake[i] = Math.round(t * dur);
  });

  // Only one hop in the air at a time: a fast double-click should retarget,
  // not stack.
  document.querySelectorAll(`.${LAYER_CLASS}`).forEach((el) => el.remove());

  const header = toEl.closest(".header");

  const layer = document.createElement("div");
  // The layer hangs off document.body, so it is outside the [data-theme] the
  // header carries — the one style that cares (the contact shadow, warm grey
  // on cream rather than black) has to be told.
  layer.className =
    header && header.getAttribute("data-theme") === "light"
      ? `${LAYER_CLASS} ${LAYER_CLASS}--light`
      : LAYER_CLASS;
  layer.setAttribute("aria-hidden", "true");
  setVars(layer, {
    "--hop-x0": `${from.x}px`,
    "--hop-y0": `${from.y}px`,
    "--hop-x1": `${to.x}px`,
    "--hop-y1": `${to.y}px`,
    "--hop-arc": `${arc}px`,
    "--hop-base": `${toRect.height / 2}px`,
    "--hop-dur": `${dur}ms`,
    "--hop-accent": accent,
    "--hop-accent-from": accentFrom,
  });

  // The trail first, so the real ball paints over its own ghosts.
  for (let g = GHOSTS; g >= 1; g--) {
    const ghost = document.createElement("span");
    ghost.className = "nav-hop nav-hop--ghost";
    ghost.style.setProperty("--g", String(g));
    ghost.style.setProperty("--g-delay", `${g * GHOST_GAP_MS}ms`);
    ghost.innerHTML = '<i class="nav-hop-ball"></i>';
    layer.appendChild(ghost);
  }

  const hop = document.createElement("span");
  hop.className = "nav-hop";
  // The contact shadow stays down on the row and shrinks as the ball climbs —
  // the cue that actually communicates height.
  hop.innerHTML = '<i class="nav-hop-shadow"></i><i class="nav-hop-ball"></i>';
  layer.appendChild(hop);

  const takeoff = document.createElement("span");
  takeoff.className = "nav-hop-burst nav-hop-burst--takeoff";
  setVars(takeoff, {
    left: `${from.x}px`,
    top: `${from.y}px`,
    "--hop-accent": accentFrom,
  });
  layer.appendChild(takeoff);

  const landing = document.createElement("span");
  landing.className = "nav-hop-burst nav-hop-burst--landing";
  setVars(landing, { left: `${to.x}px`, top: `${to.y}px` });
  layer.appendChild(landing);

  // On impact, light runs outward along the bar's bottom edge from the point
  // of contact. The header is the one element both keys share, so its own edge
  // is where the landing gets announced.
  if (header) {
    const sweep = document.createElement("span");
    sweep.className = "nav-hop-sweep";
    setVars(sweep, {
      "--sweep-y": `${Math.round(header.getBoundingClientRect().bottom)}px`,
      "--sweep-x": `${to.x}px`,
    });
    layer.appendChild(sweep);
  }

  document.body.appendChild(layer);

  // Generous: the sweep outlives the landing, and a blocked main thread can
  // deliver this late without anything being cut short.
  setTimeout(() => layer.remove(), dur + 1200);

  const now = performance.now();
  flight = { toIdx, dur, wake, accent, startedAt: now, endsAt: now + dur };
  return flight;
}

// Claimed by the header the ball is landing on, which owns the keys it lands
// among. It has to be that header and no other: navigate twice in quick
// succession and the first page's header can mount while the second hop is
// already in the air, and if it took the flight it would both fail to use it
// and leave the header that needs it with nothing — which then launches a
// duplicate hop of its own. Matching on toIdx keeps the flight in the air
// until its own destination arrives.
export function takeFlight(toIdx) {
  if (!flight || (toIdx !== undefined && flight.toIdx !== toIdx)) return null;
  const f = flight;
  flight = null;
  return f;
}

// Is a hop still on its way somewhere? The header that mounts while one is in
// the air must not launch another, whether or not the flight is addressed to
// it. The expiry is there so an unclaimed flight — a destination header that
// never mounts — cannot block hops for the rest of the session.
export const hopInFlight = () =>
  !!flight && performance.now() < flight.endsAt + 600;

// A hop is pure decoration, and the arc is exactly the motion a reduced-motion
// preference is asking us to drop.
export const hopAllowed = () =>
  typeof window !== "undefined" &&
  window.innerWidth > 768 &&
  !(
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
