// PullCord.js
// A lamp pull-cord hanging from the header theme switch. The cord is a
// Verlet rope (fixed anchor, gravity, distance constraints) with a small
// Edison bulb at the end. Drag the bulb down: the cord stretches, and past a
// threshold the bulb brightens ("armed"); let go and the theme flips while
// the cord springs back. Passing the cursor nearby nudges it; the switch
// itself gives it a kick. The loop sleeps once the rope settles.
// The bulb is the state: lit amber = light mode, dark glass = dark mode.

import React, { useCallback, useEffect, useRef, useState } from "react";
import "./PullCord.css";

const SEG = 9; // segments
const LEN = 7.2; // px per segment at rest
const REST = SEG * LEN;
const ARM = 22; // extra pull (px) that arms the toggle
const MAX = REST + 40; // furthest the cord will stretch
const SIDE = 26; // a pull cord goes down, not sideways: cap lateral drag
const VMAX = 9; // per-frame speed cap so a flick can't fling it
const G = 0.42; // gravity per frame²
const DAMP = 0.962;

const reducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

export default function PullCord({ isDark, onToggle }) {
  const svgRef = useRef(null);
  const cordRef = useRef(null);
  const sheenRef = useRef(null);
  const bulbRef = useRef(null);
  const sim = useRef(null);
  const [armed, setArmed] = useState(false);
  const [hint, setHint] = useState(false);
  const [pulling, setPulling] = useState(false);

  if (!sim.current) {
    sim.current = {
      pts: Array.from({ length: SEG + 1 }, (_, i) => ({
        x: 0,
        y: i * LEN,
        px: 0,
        py: i * LEN,
      })),
      drag: null,
      raf: 0,
      calm: 0,
      armed: false,
      downAt: null,
    };
  }

  const draw = useCallback(() => {
    const { pts } = sim.current;
    // smooth curve through segment midpoints
    let d = `M ${pts[0].x.toFixed(2)} ${pts[0].y.toFixed(2)}`;
    for (let i = 1; i < pts.length - 1; i++) {
      const mx = (pts[i].x + pts[i + 1].x) / 2;
      const my = (pts[i].y + pts[i + 1].y) / 2;
      d += ` Q ${pts[i].x.toFixed(2)} ${pts[i].y.toFixed(2)} ${mx.toFixed(
        2
      )} ${my.toFixed(2)}`;
    }
    const last = pts[pts.length - 1];
    d += ` L ${last.x.toFixed(2)} ${last.y.toFixed(2)}`;
    cordRef.current?.setAttribute("d", d);
    sheenRef.current?.setAttribute("d", d);
    const prev = pts[pts.length - 2];
    const ang =
      (Math.atan2(last.y - prev.y, last.x - prev.x) * 180) / Math.PI - 90;
    bulbRef.current?.setAttribute(
      "transform",
      `translate(${last.x.toFixed(2)} ${last.y.toFixed(
        2
      )}) rotate(${ang.toFixed(2)})`
    );
  }, []);

  const step = useCallback(() => {
    const s = sim.current;
    const { pts } = s;
    const last = pts[pts.length - 1];
    let energy = 0;

    for (let i = 1; i < pts.length; i++) {
      const p = pts[i];
      const vx = Math.max(-VMAX, Math.min(VMAX, (p.x - p.px) * DAMP));
      const vy = Math.max(-VMAX, Math.min(VMAX, (p.y - p.py) * DAMP));
      p.px = p.x;
      p.py = p.y;
      p.x += vx;
      p.y += vy + G;
      energy += Math.abs(vx) + Math.abs(vy);
    }

    let stretch = 1;
    if (s.drag) {
      // pin the bulb to the pointer, within reach
      let dx = Math.max(-SIDE, Math.min(SIDE, s.drag.x));
      let dy = Math.max(s.drag.y, 8);
      const dist = Math.hypot(dx, dy);
      if (dist > MAX) {
        dx *= MAX / dist;
        dy *= MAX / dist;
      }
      // ease toward the hand instead of teleporting: no jitter, no snap
      last.x += (dx - last.x) * 0.6;
      last.y += (dy - last.y) * 0.6;
      dx = last.x;
      dy = last.y;
      stretch = Math.max(1, Math.hypot(dx, dy) / REST);
      const isArmed = Math.hypot(dx, dy) - REST > ARM;
      if (isArmed !== s.armed) {
        s.armed = isArmed;
        setArmed(isArmed);
      }
    }

    const L = LEN * stretch;
    for (let k = 0; k < 14; k++) {
      pts[0].x = 0;
      pts[0].y = 0;
      for (let i = 0; i < pts.length - 1; i++) {
        const a = pts[i];
        const b = pts[i + 1];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const dist = Math.hypot(dx, dy) || 0.0001;
        const diff = (dist - L) / dist;
        const aFixed = i === 0;
        const bFixed = s.drag && i + 1 === pts.length - 1;
        if (aFixed && bFixed) continue;
        if (aFixed) {
          b.x -= dx * diff;
          b.y -= dy * diff;
        } else if (bFixed) {
          a.x += dx * diff;
          a.y += dy * diff;
        } else {
          a.x += dx * diff * 0.5;
          a.y += dy * diff * 0.5;
          b.x -= dx * diff * 0.5;
          b.y -= dy * diff * 0.5;
        }
      }
    }

    draw();
    s.calm = !s.drag && energy < 0.04 ? s.calm + 1 : 0;
    if (s.calm > 40) {
      s.raf = 0;
      return;
    }
    s.raf = requestAnimationFrame(step);
  }, [draw]);

  const wake = useCallback(() => {
    const s = sim.current;
    s.calm = 0;
    if (!s.raf && !reducedMotion()) s.raf = requestAnimationFrame(step);
  }, [step]);

  // velocity kick on the bulb (and a bit up the cord)
  const kick = useCallback(
    (vx, vy) => {
      const { pts } = sim.current;
      const n = pts.length;
      for (let i = Math.max(1, n - 4); i < n; i++) {
        const k = (i - (n - 4)) / 4 + 0.25;
        pts[i].px -= vx * k;
        pts[i].py -= vy * k;
      }
      wake();
    },
    [wake]
  );

  useEffect(() => {
    draw();
    const s = sim.current;
    return () => cancelAnimationFrame(s.raf);
  }, [draw]);

  // the switch flipped (by any route): give the cord a little swing
  const firstTheme = useRef(true);
  useEffect(() => {
    if (firstTheme.current) {
      firstTheme.current = false;
      return;
    }
    if (!sim.current.drag) kick(isDark ? -1.4 : 1.4, -0.8);
  }, [isDark, kick]);

  // First visit: sway, give a little demo tug, and say "Pull me" — twice,
  // then never again once they've touched it (or seen it both times).
  const markSeen = useCallback(() => {
    try {
      localStorage.setItem("pullcord.seen", "1");
    } catch (e) {
      /* ignore */
    }
  }, []);
  useEffect(() => {
    let seen = false;
    try {
      seen = localStorage.getItem("pullcord.seen") === "1";
    } catch (e) {
      /* ignore */
    }
    if (seen) return undefined;
    const timers = [];
    const at = (ms, fn) => timers.push(setTimeout(fn, ms));
    const routine = (t0) => {
      at(t0, () => setHint(true));
      if (!reducedMotion()) {
        at(t0 + 0, () => kick(2.2, 0));
        at(t0 + 650, () => kick(-3, 0));
        at(t0 + 1300, () => kick(2.4, 0));
        at(t0 + 2100, () => kick(0, 4.5)); // demo tug down…
        at(t0 + 2350, () => kick(0, -3.5)); // …and back
      }
      at(t0 + 4800, () => setHint(false));
    };
    routine(1600);
    routine(11000);
    at(16000, markSeen);
    return () => timers.forEach(clearTimeout);
  }, [kick, markSeen]);

  // the cursor brushing past pushes the bulb
  useEffect(() => {
    if (reducedMotion()) return undefined;
    let lx = null;
    let ly = null;
    const onMove = (e) => {
      const svg = svgRef.current;
      if (!svg || sim.current.drag) return;
      const r = svg.getBoundingClientRect();
      const ax = r.left + r.width / 2;
      const { pts } = sim.current;
      const last = pts[pts.length - 1];
      const bx = ax + last.x;
      const by = r.top + last.y + 14;
      const dist =
        lx !== null ? Math.hypot(e.clientX - bx, e.clientY - by) : 999;
      // Only a glancing brush moves it. Inside the grab zone, or heading
      // towards the bulb, leave it still so it's easy to catch.
      const mx = e.clientX - lx;
      const my = e.clientY - ly;
      const towards = mx * (bx - e.clientX) + my * (by - e.clientY) > 0;
      if (dist > 20 && dist < 38 && !towards) {
        const vx = Math.max(-2.2, Math.min(2.2, mx * 0.14));
        const vy = Math.max(-1, Math.min(1, my * 0.06));
        if (Math.abs(vx) + Math.abs(vy) > 0.25) kick(vx, vy);
      }
      lx = e.clientX;
      ly = e.clientY;
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => window.removeEventListener("pointermove", onMove);
  }, [kick]);

  // pointer in rope space, shifted by where on the bulb it was grabbed
  const grabOffset = useRef({ x: 0, y: 0 });
  const rawPoint = (e) => {
    const r = svgRef.current.getBoundingClientRect();
    return { x: e.clientX - (r.left + r.width / 2), y: e.clientY - r.top - 12 };
  };
  const localPoint = (e) => {
    const p = rawPoint(e);
    return { x: p.x + grabOffset.current.x, y: p.y + grabOffset.current.y };
  };

  // Window-level listeners for the drag: pointer capture on an SVG <g> is
  // unreliable, and a lost pointerup would leave the cord stuck pulled.
  const dragHandlers = useRef(null);
  const onPointerDown = (e) => {
    e.preventDefault();
    e.stopPropagation();
    const { pts } = sim.current;
    const last = pts[pts.length - 1];
    const raw = rawPoint(e);
    grabOffset.current = { x: last.x - raw.x, y: last.y - raw.y };
    setHint(false);
    markSeen();
    sim.current.drag = localPoint(e);
    sim.current.downAt = { x: e.clientX, y: e.clientY, t: performance.now() };
    setPulling(true);
    wake();
    const move = (ev) => onPointerMove(ev);
    const up = (ev) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      dragHandlers.current = null;
      release(ev);
    };
    dragHandlers.current = { move, up };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };
  useEffect(
    () => () => {
      const h = dragHandlers.current;
      if (h) {
        window.removeEventListener("pointermove", h.move);
        window.removeEventListener("pointerup", h.up);
        window.removeEventListener("pointercancel", h.up);
      }
    },
    []
  );
  const onPointerMove = (e) => {
    if (!sim.current.drag) return;
    sim.current.drag = localPoint(e);
    wake();
  };
  const release = (e) => {
    const s = sim.current;
    if (!s.drag) return;
    const moved = s.downAt
      ? Math.hypot(e.clientX - s.downAt.x, e.clientY - s.downAt.y)
      : 99;
    const wasArmed = s.armed;
    s.drag = null;
    s.armed = false;
    setArmed(false);
    setPulling(false);
    if (wasArmed || moved < 4) {
      onToggle();
      kick(0, -5); // snap back up
    } else {
      wake();
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      setHint(false);
      markSeen();
      kick(0, 5);
      setTimeout(() => {
        onToggle();
        kick(0, -5);
      }, 140);
    }
  };

  return (
    <span
      className={`pc ${isDark ? "is-dark" : "is-light"} ${
        armed ? "is-armed" : ""
      } ${pulling ? "is-pulling" : ""}`}
    >
      <svg
        ref={svgRef}
        className="pc-svg"
        width="120"
        height="200"
        viewBox="-60 -12 120 200"
        aria-hidden="false"
      >
        <defs>
          <radialGradient id="pcGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#ffd27a" stopOpacity="0.9" />
            <stop offset="45%" stopColor="#ffb347" stopOpacity="0.35" />
            <stop offset="100%" stopColor="#ffb347" stopOpacity="0" />
          </radialGradient>
          <radialGradient id="pcGlass" cx="40%" cy="35%" r="70%">
            <stop offset="0%" stopColor="#fff6dc" />
            <stop offset="55%" stopColor="#ffd98f" />
            <stop offset="100%" stopColor="#f2a33a" />
          </radialGradient>
          <radialGradient id="pcGlassOff" cx="38%" cy="32%" r="75%">
            <stop offset="0%" stopColor="rgba(220,222,255,0.35)" />
            <stop offset="60%" stopColor="rgba(120,124,170,0.16)" />
            <stop offset="100%" stopColor="rgba(60,62,90,0.28)" />
          </radialGradient>
        </defs>
        <path ref={cordRef} className="pc-cord" />
        <path ref={sheenRef} className="pc-sheen" />
        <g
          ref={bulbRef}
          className="pc-bulb"
          role="button"
          tabIndex={0}
          aria-label={
            isDark
              ? "Pull the cord to turn the lights on (light mode)"
              : "Pull the cord to turn the lights off (dark mode)"
          }
          onPointerDown={onPointerDown}
          onClick={(e) => e.stopPropagation()}
          onKeyDown={onKeyDown}
        >
          <title>{isDark ? "Pull for light mode" : "Pull for dark mode"}</title>
          {/* generous invisible grab area */}
          <circle cx="0" cy="16" r="20" fill="transparent" />
          <circle
            className="pc-halo"
            cx="0"
            cy="17"
            r="26"
            fill="url(#pcGlow)"
          />
          {/* bead where the cord meets the cap */}
          <circle cx="0" cy="-1" r="1.8" className="pc-bead" />
          {/* screw cap */}
          <rect
            x="-3.6"
            y="0"
            width="7.2"
            height="6.4"
            rx="1.4"
            className="pc-cap"
          />
          <line x1="-3.6" y1="2.2" x2="3.6" y2="2.2" className="pc-thread" />
          <line x1="-3.6" y1="4.2" x2="3.6" y2="4.2" className="pc-thread" />
          {/* glass */}
          <path
            className="pc-glass"
            d="M -2.8 6.2 C -2.8 9 -8 9.6 -8 15.6 A 8 8 0 1 0 8 15.6 C 8 9.6 2.8 9 2.8 6.2 Z"
          />
          {/* filament */}
          <path
            className="pc-filament"
            d="M -1.6 7 L -2.4 12.6 Q -1.2 15.6 0 13 Q 1.2 15.6 2.4 12.6 L 1.6 7"
          />
          {/* specular */}
          <path className="pc-spec" d="M -5.2 12.4 Q -5.6 16.2 -3.4 19" />
        </g>
      </svg>
      <span className={`pc-hint ${hint ? "show" : ""}`} aria-hidden="true">
        Pull me
        <i />
      </span>
    </span>
  );
}
